import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gelu_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__device__ __forceinline__ float4 gelu4(float4 v) {
    const float c = 0.7978845608028654f; // sqrt(2/pi)
    const float a = 0.044715f;
    float t0 = c * (v.x + a * v.x * v.x * v.x);
    float t1 = c * (v.y + a * v.y * v.y * v.y);
    float t2 = c * (v.z + a * v.z * v.z * v.z);
    float t3 = c * (v.w + a * v.w * v.w * v.w);
    v.x = 0.5f * v.x * (1.0f + tanhf(t0));
    v.y = 0.5f * v.y * (1.0f + tanhf(t1));
    v.z = 0.5f * v.z * (1.0f + tanhf(t2));
    v.w = 0.5f * v.w * (1.0f + tanhf(t3));
    return v;
}
__global__ void gelu_kernel_vec4(const float4* __restrict__ x, float4* __restrict__ y, int n4) {
    int base = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    // Increase memory-level parallelism by unrolling 8 float4 loads/stores
    // (32 floats) per grid-stride loop iteration to better hide global
    // memory latency and push closer to peak DRAM throughput.
    const int UNROLL = 8;
    for (int idx = base; idx < n4; idx += stride * UNROLL) {
        #pragma unroll
        for (int k = 0; k < UNROLL; ++k) {
            int id = idx + stride * k;
            if (id < n4) {
                float4 v = __ldcs(&x[id]);
                v = gelu4(v);
                __stcs(&y[id], v);
            }
        }
    }
}
__global__ void gelu_kernel_scalar(const float* __restrict__ x, float* __restrict__ y, int n, int offset) {
    const float c = 0.7978845608028654f;
    const float a = 0.044715f;
    for (int idx = blockIdx.x * blockDim.x + threadIdx.x + offset;
         idx < n;
         idx += blockDim.x * gridDim.x) {
        float xi = __ldcs(&x[idx]);
        float t = c * (xi + a * xi * xi * xi);
        __stcs(&y[idx], 0.5f * xi * (1.0f + tanhf(t)));
    }
}
torch::Tensor gelu_cuda(torch::Tensor x) {
    auto y = torch::empty_like(x);
    int n = x.numel();
    int n4 = n / 4;
    int rem_start = n4 * 4;
    static int sm_count = 0;
    if (sm_count == 0) {
        int device;
        cudaGetDevice(&device);
        cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, device);
        if (sm_count < 1) sm_count = 1;
    }
    if (n4 > 0) {
        const int threads = 256;
        int blocks_needed = (n4 + threads - 1) / threads;
        int blocks_persistent = sm_count * 32; // saturate SMs; grid-stride loop covers remainder
        int blocks = blocks_needed < blocks_persistent ? blocks_needed : blocks_persistent;
        if (blocks < 1) blocks = 1;
        gelu_kernel_vec4<<<blocks, threads>>>(
            reinterpret_cast<const float4*>(x.data_ptr<float>()),
            reinterpret_cast<float4*>(y.data_ptr<float>()),
            n4
        );
    }
    int rem = n - rem_start;
    if (rem > 0) {
        const int threads = 256;
        int blocks_needed = (rem + threads - 1) / threads;
        int blocks_persistent = sm_count * 32;
        int blocks = blocks_needed < blocks_persistent ? blocks_needed : blocks_persistent;
        if (blocks < 1) blocks = 1;
        gelu_kernel_scalar<<<blocks, threads>>>(
            x.data_ptr<float>(),
            y.data_ptr<float>(),
            n,
            rem_start
        );
    }
    return y;
}
"""

gelu_cpp_source = "torch::Tensor gelu_cuda(torch::Tensor x);"

gelu_module = load_inline(
    name="gelu_module",
    cpp_sources=gelu_cpp_source,
    cuda_sources=gelu_source,
    functions=["gelu_cuda"],
    extra_cuda_cflags=["-use_fast_math"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.gelu = gelu_module

    def forward(self, x):
        x = x.contiguous()
        return self.gelu.gelu_cuda(x)


